package java.util.concurrent;
public class Semaphore implements java.io.Serializable {
 private int permits;private final boolean fair;public Semaphore(int permits){this(permits,false);}public Semaphore(int permits,boolean fair){this.permits=permits;this.fair=fair;}public boolean isFair(){return fair;}public int availablePermits(){return permits;}public int drainPermits(){int n=permits;permits=0;return n;}protected void reducePermits(int n){if(n<0)throw new IllegalArgumentException();permits-=n;}public void release(){release(1);}public void release(int n){if(n<0)throw new IllegalArgumentException();if(permits+n<permits)throw new Error("Maximum permit count exceeded");permits+=n;}public boolean tryAcquire(){return tryAcquire(1);}public boolean tryAcquire(int n){if(n<0)throw new IllegalArgumentException();if(permits<n)return false;permits-=n;return true;}public void acquire()throws InterruptedException{acquire(1);}public void acquire(int n)throws InterruptedException{if(Thread.interrupted())throw new InterruptedException();if(!tryAcquire(n)){java.lang.VMThread.runPending();if(!tryAcquire(n))throw new IllegalStateException();}}public void acquireUninterruptibly(){acquireUninterruptibly(1);}public void acquireUninterruptibly(int n){try{acquire(n);}catch(InterruptedException e){Thread.currentThread().interrupt();}}public boolean tryAcquire(long n,TimeUnit u)throws InterruptedException{return tryAcquire(1,n,u);}public boolean tryAcquire(int p,long n,TimeUnit u)throws InterruptedException{if(u==null)throw new NullPointerException();if(Thread.interrupted())throw new InterruptedException();if(tryAcquire(p))return true;java.lang.VMThread.runPending();return tryAcquire(p);}public boolean hasQueuedThreads(){return false;}public int getQueueLength(){return 0;}public String toString(){return super.toString()+"[Permits = "+permits+"]";}
}
